(4603266, 662609, 84736, '<td valign="top">i love the look of this pic, especially the sky. i feel that if it was shot without the support in the middle of the frame it would have ben better though.</td>', 'i love the look of this pic, especially the sky. i feel that if it was shot without the support in the middle of the frame it would have ben better though.', '2008-04-01 17:09:54.000000', NULL, 1),
(4603280, 663545, 50695, '<td valign="top">beautiful. can''t decide how I feel about the collar, but the rest is perfect. I''ve been chastising people lately for compositions like this, but your subject has a great shape and creates wonderful negative and positive space, so it works.</td>', 'beautiful. can''t decide how I feel about the collar, but the rest is perfect. I''ve been chastising people lately for compositions like this, but your subject has a great shape and creates wonderful negative and positive space, so it works.', '2008-04-01 17:15:36.000000', NULL, 1),
(4603281, 663909, 50695, '<td valign="top">I love it when something mundane is made beautiful.</td>', 'I love it when something mundane is made beautiful.', '2008-04-01 17:15:53.000000', NULL, 1),
