(4603287, 663908, 50695, '<td valign="top">I wonder if windowsill is going to become the next big genre at dpc. I hope so! This is a good, primitive example, and the title shows that you understand the poetry of an image like this.</td>', 'I wonder if windowsill is going to become the next big genre at dpc. I hope so! This is a good, primitive example, and the title shows that you understand the poetry of an image like this.', '2008-04-01 17:18:04.000000', NULL, 1),
(4603290, 663564, 50695, '<td valign="top">The rotation does more than just a folding heart trick. It creates a disorientation that allows the music to begin.</td>', 'The rotation does more than just a folding heart trick. It creates a disorientation that allows the music to begin.', '2008-04-01 17:19:02.000000', NULL, 1),
(4603292, 663910, 50695, '<td valign="top">good composition, good capture, well processed. you make it look easy! :)</td>', 'good composition, good capture, well processed. you make it look easy! :)', '2008-04-01 17:19:46.000000', NULL, 1),
(4603293, 663645, 50695, '<td valign="top">This looks like a parallel universe. Remarkably cosmic.</td>', 'This looks like a parallel universe. Remarkably cosmic.', '2008-04-01 17:20:18.000000', NULL, 1),
(4603298, 662583, 50695, '<td valign="top">having color only on the left side seems unbalanced to me, distracting. Otherwise, this is an amazing image. The texture of the feathers is just incredible, and there''s a strange poignance to the pose.</td>', 'having color only on the left side seems unbalanced to me, distracting. Otherwise, this is an amazing image. The texture of the feathers is just incredible, and there''s a strange poignance to the pose.', '2008-04-01 17:21:59.000000', NULL, 1),
