(4603790, 662559, 31637, '<td valign="top">Interested in knowing what Church this is. Great shot.</td>', 'Interested in knowing what Church this is. Great shot.', '2008-04-01 21:16:18.000000', NULL, 1),
(4603796, 663234, 31637, '<td valign="top">very nice shot, but not sure if the fishing pole is the main focus here, I would have liked to see one of the towers of the Manhattan Bridge in a tight crop tho, and maybe you would meet the theme.. 5</td>', 'very nice shot, but not sure if the fishing pole is the main focus here, I would have liked to see one of the towers of the Manhattan Bridge in a tight crop tho, and maybe you would meet the theme.. 5', '2008-04-01 21:18:20.000000', NULL, 1),
(4604020, 663803, 81609, '<td valign="top">Very eggsacious, good job. I hope you''ll let us know the PP for this shot. Truly beautiful.</td>', 'Very eggsacious, good job. I hope you''ll let us know the PP for this shot. Truly beautiful.', '2008-04-01 22:47:43.000000', NULL, 1),
