(4604642, 663934, 90372, '<td valign="top">Ouch!!!</td>', 'Ouch!!!', '2008-04-02 01:30:18.000000', NULL, 1),
(4604904, 663916, 12661, '<td valign="top">The repeating pattern of the arches adds a nice balance to the image and gives an overall pleasing composition. However, the colors are less than pleasing to me. The image appears a bit too high in temperature and there is no definition in the sky.</td>', 'The repeating pattern of the arches adds a nice balance to the image and gives an overall pleasing composition. However, the colors are less than pleasing to me. The image appears a bit too high in temperature and there is no definition in the sky.', '2008-04-02 02:34:47.000000', NULL, 1),
(4604911, 663715, 12661, '<td valign="top">Spot on!!!! Nice contrast, excellent saturation, perfect focus, and smooth background. An old rule of thumb for animal photography is that if the eye is in focus, the rest falls into place.</td>', 'Spot on!!!! Nice contrast, excellent saturation, perfect focus, and smooth background. An old rule of thumb for animal photography is that if the eye is in focus, the rest falls into place.', '2008-04-02 02:36:25.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4604915, 663932, 12661, '<td valign="top">Beautiful lighting and nice use of negative space. A spectacular image to say the least.</td>', 'Beautiful lighting and nice use of negative space. A spectacular image to say the least.', '2008-04-02 02:37:26.000000', NULL, 1),
(4604931, 663863, 12661, '<td valign="top">I like the colors and the composition of this photograph. Then again, I am a sucker for night photography. My only doubt is with the blur caused by the unlit swings from the ride on the left. I am torn between seeing them as a distraction vs an mystic swirl that adds to the intrigue. I''ll go with the later.</td>', 'I like the colors and the composition of this photograph. Then again, I am a sucker for night photography. My only doubt is with the blur caused by the unlit swings from the ride on the left. I am torn between seeing them as a distraction vs an mystic swirl that adds to the intrigue. I''ll go with the later.', '2008-04-02 02:41:17.000000', NULL, 1),
(4604938, 663831, 12661, '<td valign="top">Despite your title, I still have no idea what I am looking at. Regardless the colors are pleasing and the lighting is well balanced. The image paints a cool and soothing sensation, albeit slightly interrupted by the few drops that remained in sharp focus.</td>', 'Despite your title, I still have no idea what I am looking at. Regardless the colors are pleasing and the lighting is well balanced. The image paints a cool and soothing sensation, albeit slightly interrupted by the few drops that remained in sharp focus.', '2008-04-02 02:43:46.000000', NULL, 1),
(4604940, 663476, 12661, '<td valign="top">The contrast between the structure and the sky is very well done. The composition and pattern repetition is also very nice. I would have preferred a wider crop to give me an idea of what I am looking at, but that is just my personal preference.</td>', 'The contrast between the structure and the sky is very well done. The composition and pattern repetition is also very nice. I would have preferred a wider crop to give me an idea of what I am looking at, but that is just my personal preference.', '2008-04-02 02:45:14.000000', NULL, 1),
(4604942, 663585, 12661, '<td valign="top">I like the use of leading lines to take your eyes across and back over the image. It would have liked it better if there was a way to not include the lower roadbed and capture the image later in the day to avoid the sharp shadows on the uprights.</td>', 'I like the use of leading lines to take your eyes across and back over the image. It would have liked it better if there was a way to not include the lower roadbed and capture the image later in the day to avoid the sharp shadows on the uprights.', '2008-04-02 02:47:50.000000', NULL, 1),
(4604947, 663432, 12661, '<td valign="top">An interesting photo, but I find it a bit too close-up for my taste. Also, the exposure on the lower left is hiding the form of the ear.</td>', 'An interesting photo, but I find it a bit too close-up for my taste. Also, the exposure on the lower left is hiding the form of the ear.', '2008-04-02 02:50:01.000000', NULL, 1),
(4604957, 663324, 12661, '<td valign="top">These types of photos are the hardest for me to score and I find myself sitting back and just staring at it for a few minutes waiting for it to say something. In this case, the lower portion I find very pleasing, particularly the change in brightness as you go from the corners to the edge. The background, however, I am having a difficult time appreciating. The seemingly random presentations of colors and brightness levels don''t harmonize with the lower portion. As far as the orbs, the two above the depression do play nicely with the bottom part, but the one on the right doesn''t look like it belongs.</td>', 'These types of photos are the hardest for me to score and I find myself sitting back and just staring at it for a few minutes waiting for it to say something. In this case, the lower portion I find very pleasing, particularly the change in brightness as you go from the corners to the edge. The background, however, I am having a difficult time appreciating. The seemingly random presentations of colors and brightness levels don''t harmonize with the lower portion. As far as the orbs, the two above the depression do play nicely with the bottom part, but the one on the right doesn''t look like it belongs.', '2008-04-02 02:55:45.000000', NULL, 1),
(4604963, 663771, 12661, '<td valign="top">I like the sharp focus and the composition of the goose itself in this photo. However, I think it would have more impact if you included the entire reflection and not cropped it at its neck. Also, the lighting looks like it was taken on a bright cloudless afternoon. That kind of lighting throws very distracting shadows such as on the left side of its head as well as under the tail feathers.</td>', 'I like the sharp focus and the composition of the goose itself in this photo. However, I think it would have more impact if you included the entire reflection and not cropped it at its neck. Also, the lighting looks like it was taken on a bright cloudless afternoon. That kind of lighting throws very distracting shadows such as on the left side of its head as well as under the tail feathers.', '2008-04-02 02:59:16.000000', NULL, 1),
