(4613180, 663310, 91862, '<td valign="top">I love the color!</td>', 'I love the color!', '2008-04-04 09:35:12.000000', NULL, 1),
(4613184, 663489, 91862, '<td valign="top">Nice shot, but there is a lot going on.  Almost too much.  I do like the framing and the softness though.</td>', 'Nice shot, but there is a lot going on.  Almost too much.  I do like the framing and the softness though.', '2008-04-04 09:36:05.000000', NULL, 1),
(4613186, 663852, 91862, '<td valign="top">Very nicely done.  Well exposed and clear.  The color is great and you really get a sense of being there.  Thanks for this one!</td>', 'Very nicely done.  Well exposed and clear.  The color is great and you really get a sense of being there.  Thanks for this one!', '2008-04-04 09:37:27.000000', NULL, 1),
(4613193, 663187, 91862, '<td valign="top">I really love the disconnect.  Well done.  Tones are awesome!</td>', 'I really love the disconnect.  Well done.  Tones are awesome!', '2008-04-04 09:39:07.000000', NULL, 1),
(4613194, 662337, 91862, '<td valign="top">Very well framed!</td>', 'Very well framed!', '2008-04-04 09:39:31.000000', NULL, 1),
(4613196, 663791, 91862, '<td valign="top">Interesting exposure.  The colors are great!</td>', 'Interesting exposure.  The colors are great!', '2008-04-04 09:40:09.000000', NULL, 1),
(4613198, 663205, 91862, '<td valign="top">Interesting take on such a common item!  I had no idea what I was looking at until I read the title.  Well done.</td>', 'Interesting take on such a common item!  I had no idea what I was looking at until I read the title.  Well done.', '2008-04-04 09:40:56.000000', NULL, 1),
(4613199, 662583, 91862, '<td valign="top">Very emotional.  I like the harshness of this image.</td>', 'Very emotional.  I like the harshness of this image.', '2008-04-04 09:41:19.000000', NULL, 1),
(4613203, 663432, 91862, '<td valign="top">That''s almost creepy.  I like it!  Well done.</td>', 'That''s almost creepy.  I like it!  Well done.', '2008-04-04 09:42:40.000000', NULL, 1),
(4613205, 661719, 91862, '<td valign="top">I like the shadow work.  It''s very harsh and I like that in an image like this.</td>', 'I like the shadow work.  It''s very harsh and I like that in an image like this.', '2008-04-04 09:43:13.000000', NULL, 1),
(4613210, 662966, 91862, '<td valign="top">Nice play!  Almost poetic.  I really like this one.</td>', 'Nice play!  Almost poetic.  I really like this one.', '2008-04-04 09:44:29.000000', NULL, 1),
(4613215, 662437, 91862, '<td valign="top">Can you say "motorcycle"?  This is an awsome example of an "s-curve"  I like it.</td>', 'Can you say "motorcycle"?  This is an awsome example of an "s-curve"  I like it.', '2008-04-04 09:45:21.000000', NULL, 1),
(4613218, 663927, 91862, '<td valign="top">Very well done.  Nice color, nice curve, use of lighting, well exposed.  I like everything about this shot.</td>', 'Very well done.  Nice color, nice curve, use of lighting, well exposed.  I like everything about this shot.', '2008-04-04 09:46:04.000000', NULL, 1),
(4613221, 663920, 91862, '<td valign="top">This is almost a feature photo.  I like how the curve is more implied than literal.  Well played.</td>', 'This is almost a feature photo.  I like how the curve is more implied than literal.  Well played.', '2008-04-04 09:46:39.000000', NULL, 1),
(4613224, 663579, 91862, '<td valign="top">To be honest...I didn''t like this at first.  But the more I look at it, the more it draws me in.  I really  like the high contrast.  I love that it''s in black and white.  And the more I study this one, the more I love the distortion of the wider angle lens.  Very nice shot.</td>', 'To be honest...I didn''t like this at first.  But the more I look at it, the more it draws me in.  I really  like the high contrast.  I love that it''s in black and white.  And the more I study this one, the more I love the distortion of the wider angle lens.  Very nice shot.', '2008-04-04 09:48:11.000000', NULL, 1),
(4613230, 663571, 91862, '<td valign="top">This shot is almost comical to me!  I love it.  It looks like there is a lot of movement in the shot.</td>', 'This shot is almost comical to me!  I love it.  It looks like there is a lot of movement in the shot.', '2008-04-04 09:52:13.000000', NULL, 1),
