(4614216, 663848, 78196, '<td valign="top">You''ll probably have been told this already, but you''ve got to lose the border. The image fits the challenge but not in an especially engaging way - a good monochrome conversion might improve things a little.</td>', 'You''ll probably have been told this already, but you''ve got to lose the border. The image fits the challenge but not in an especially engaging way - a good monochrome conversion might improve things a little.', '2008-04-04 15:09:53.000000', NULL, 1),
(4614220, 663497, 78196, '<td valign="top">Well exposed although lacking a little in contrast - the main issue here is some pretty nasty CA''s - especially the green one under the arch on the right - this can be removed, albeit painstakingly, under advanced editing in PS.</td>', 'Well exposed although lacking a little in contrast - the main issue here is some pretty nasty CA''s - especially the green one under the arch on the right - this can be removed, albeit painstakingly, under advanced editing in PS.', '2008-04-04 15:12:07.000000', NULL, 1),
