(4616821, 663807, 66524, '<td valign="top">My first reaction...Ooooh, this is fun!  indeed it remains so.  Well done</td>', 'My first reaction...Ooooh, this is fun!  indeed it remains so.  Well done', '2008-04-05 18:52:25.000000', NULL, 1),
(4616826, 663539, 18197, '<td valign="top">Clearly out of the box for a good long time. Technically a fine photo (focus, comp, brightness and contrast, and it does carry an emotional payload). But I''m struggling with the subject matter. No one wants a true accounting of where their breakfast sausage comes from (speaking metaphorically - unless you live in China).</td>', 'Clearly out of the box for a good long time. Technically a fine photo (focus, comp, brightness and contrast, and it does carry an emotional payload). But I''m struggling with the subject matter. No one wants a true accounting of where their breakfast sausage comes from (speaking metaphorically - unless you live in China).', '2008-04-05 18:54:37.000000', NULL, 1),
(4616835, 663803, 66524, '<td valign="top">beautiful lighting</td>', 'beautiful lighting', '2008-04-05 18:58:56.000000', NULL, 1),
(4616905, 662658, 2134, '<td valign="top">I really like the color combination, however, the mountain is a little blown out towards the top.</td>', 'I really like the color combination, however, the mountain is a little blown out towards the top.', '2008-04-05 19:31:05.000000', NULL, 1),
(4616913, 663310, 2134, '<td valign="top">Great composition and colors... very eye appealing!</td>', 'Great composition and colors... very eye appealing!', '2008-04-05 19:33:25.000000', NULL, 1),
(4616917, 662602, 2134, '<td valign="top">I like the idea behind this shot, but it''s just a little to soft.</td>', 'I like the idea behind this shot, but it''s just a little to soft.', '2008-04-05 19:34:50.000000', NULL, 1),
(4616925, 663622, 2134, '<td valign="top">I would like to see a little more of this in focus, it was a good subject for the challenge.</td>', 'I would like to see a little more of this in focus, it was a good subject for the challenge.', '2008-04-05 19:38:26.000000', NULL, 1),
(4616928, 662357, 2134, '<td valign="top">Very striking... the lighting is wonderful!</td>', 'Very striking... the lighting is wonderful!', '2008-04-05 19:38:52.000000', NULL, 1),
