(4616936, 663432, 2134, '<td valign="top">Cropped to close and a little to out of focus for me.</td>', 'Cropped to close and a little to out of focus for me.', '2008-04-05 19:42:55.000000', NULL, 1),
(4616940, 663190, 2134, '<td valign="top">I like this... the softness in the colors, the processing, very nice.  The only thing I may have done a little different was not have cropped the top and the right side off.</td>', 'I like this... the softness in the colors, the processing, very nice.  The only thing I may have done a little different was not have cropped the top and the right side off.', '2008-04-05 19:45:00.000000', NULL, 1),
(4616944, 663791, 2134, '<td valign="top">I like the combination of all the curves in this shot... the more I look the more I see.  Very nice.</td>', 'I like the combination of all the curves in this shot... the more I look the more I see.  Very nice.', '2008-04-05 19:46:01.000000', NULL, 1),
(4616945, 663709, 2134, '<td valign="top">Beautiful DOF and colors.  This shot really jumps out!</td>', 'Beautiful DOF and colors.  This shot really jumps out!', '2008-04-05 19:46:58.000000', NULL, 1),
(4616947, 663899, 2134, '<td valign="top">I like the color saturation in this shot, the road really pops out.</td>', 'I like the color saturation in this shot, the road really pops out.', '2008-04-05 19:47:42.000000', NULL, 1),
(4616949, 663803, 2134, '<td valign="top">Very creative... wonderful lighting!</td>', 'Very creative... wonderful lighting!', '2008-04-05 19:49:44.000000', NULL, 1),
(4616950, 663572, 2134, '<td valign="top">Fits the challenge very well, the lighting is nice also.  There is just a little too much blue tint for me.</td>', 'Fits the challenge very well, the lighting is nice also.  There is just a little too much blue tint for me.', '2008-04-05 19:51:07.000000', NULL, 1),
(4616953, 663927, 2134, '<td valign="top">This is a very nice photo.  The time of day you was a good choice for this. The light trails really set off the curves.</td>', 'This is a very nice photo.  The time of day you was a good choice for this. The light trails really set off the curves.', '2008-04-05 19:53:06.000000', NULL, 1),
(4616957, 663914, 2134, '<td valign="top">This is a great shot.. all of the curves, the reflections, the colors, it all works.</td>', 'This is a great shot.. all of the curves, the reflections, the colors, it all works.', '2008-04-05 19:56:22.000000', NULL, 1),
