(4616983, 663819, 2134, '<td valign="top">The lighting on this is very nice.</td>', 'The lighting on this is very nice.', '2008-04-05 20:18:18.000000', NULL, 1),
(4616992, 663614, 16046, '<td valign="top">Excellent dof, color selection</td>', 'Excellent dof, color selection', '2008-04-05 20:22:31.000000', NULL, 1),
(4617059, 663927, 20941, '<td valign="top">Awesome shot!!!</td>', 'Awesome shot!!!', '2008-04-05 21:34:18.000000', NULL, 1),
(4617062, 663837, 20941, '<td valign="top">Gorgeous image!!! Wonderful entry</td>', 'Gorgeous image!!! Wonderful entry', '2008-04-05 21:35:45.000000', NULL, 1),
(4617069, 663408, 1031, '<td valign="top">Not what I was expecting from the title :-)<br/> <br/>I like the combination of curving and straight/leading lines.</td>', 'Not what I was expecting from the title :-) I like the combination of curving and straight/leading lines.', '2008-04-05 21:45:04.000000', NULL, 1),
(4617079, 663926, 1031, '<td valign="top">Good use of an "implied" line -- cool how they follow the edges of the clouds.</td>', 'Good use of an "implied" line -- cool how they follow the edges of the clouds.', '2008-04-05 21:49:23.000000', NULL, 1),
(4617091, 663902, 1031, '<td valign="top">I''m trying to remember if I''ve driven over that bridge ... I know I''ve never seen it from that angle -- nice. :-)</td>', 'I''m trying to remember if I''ve driven over that bridge ... I know I''ve never seen it from that angle -- nice. :-)', '2008-04-05 21:52:30.000000', NULL, 1),
(4617104, 663899, 1031, '<td valign="top">I know a piece of road very similar to this -- nice angle and perspective to get in so many wiggles in the road.</td>', 'I know a piece of road very similar to this -- nice angle and perspective to get in so many wiggles in the road.', '2008-04-05 21:55:12.000000', NULL, 1),
(4617117, 663050, 1031, '<td valign="top">At least as I see it, this is not only a well-executed still-life, but a cool optical illusion of a gradient in the wide border.</td>', 'At least as I see it, this is not only a well-executed still-life, but a cool optical illusion of a gradient in the wide border.', '2008-04-05 22:00:56.000000', NULL, 1),
(4617130, 663920, 1031, '<td valign="top">If that pitcher''s left-handed I''d take out insurance on his arm right now. ;-)<br/>Excellent action capture, use of motion blur.</td>', 'If that pitcher''s left-handed I''d take out insurance on his arm right now. ;-)Excellent action capture, use of motion blur.', '2008-04-05 22:06:56.000000', NULL, 1),
(4617138, 663934, 1031, '<td valign="top">Ouch!</td>', 'Ouch!', '2008-04-05 22:09:04.000000', NULL, 1),
(4617145, 663917, 1031, '<td valign="top">Interesting veriation on the water-drop theme.</td>', 'Interesting veriation on the water-drop theme.', '2008-04-05 22:10:49.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4617194, 663628, 1031, '<td valign="top">I built a model of one of these way back when ... :-)</td>', 'I built a model of one of these way back when ... :-)', '2008-04-05 22:25:09.000000', NULL, 1),
(4617237, 663894, 29011, '<td valign="top">Beautiful macro. Very user Ursula style like.</td>', 'Beautiful macro. Very user Ursula style like.', '2008-04-05 22:41:43.000000', NULL, 1),
(4617239, 663694, 29011, '<td valign="top">Simple shapes arranged in an appealing way. Cool colors and nice composition with control of DOF. Using the same shapes over again, this is where less is more.</td>', 'Simple shapes arranged in an appealing way. Cool colors and nice composition with control of DOF. Using the same shapes over again, this is where less is more.', '2008-04-05 22:43:05.000000', NULL, 1),
(4617240, 663707, 29011, '<td valign="top">Beautiful! Very nicely presented.</td>', 'Beautiful! Very nicely presented.', '2008-04-05 22:43:28.000000', NULL, 1),
(4617241, 663408, 29011, '<td valign="top">Cool perspective. I see a hint of HDR which I quite like here. The style of it. Just the edges of the building against the sky look a bit muddy.</td>', 'Cool perspective. I see a hint of HDR which I quite like here. The style of it. Just the edges of the building against the sky look a bit muddy.', '2008-04-05 22:44:36.000000', NULL, 1),
(4617242, 663050, 29011, '<td valign="top">A refreshing still life. Very clever what you did with the digital framing. It blends in really well with the shot.</td>', 'A refreshing still life. Very clever what you did with the digital framing. It blends in really well with the shot.', '2008-04-05 22:45:24.000000', NULL, 1),
(4617245, 663914, 29011, '<td valign="top">Way cool shot. The composition is perfect. One of my faves from the challenge. The HDR is very well done, very subtle and the outcome really nice. My only nitpicks are, the edges look slightly haloed, and somewhat oversharpening in certain areas.</td>', 'Way cool shot. The composition is perfect. One of my faves from the challenge. The HDR is very well done, very subtle and the outcome really nice. My only nitpicks are, the edges look slightly haloed, and somewhat oversharpening in certain areas.', '2008-04-05 22:48:01.000000', NULL, 1),
